function applySort(items,key,dir){
  if(!key)return items;
  if(key==="site"){
    return [...items].sort((a,b)=>{
      const va=a.site||"",vb=b.site||"";
      if(va<vb)return dir==="asc"?-1:1;
      if(va>vb)return dir==="asc"?1:-1;
      return (a.name||"").localeCompare(b.name||"");
    });
  }
  return [...items].sort((a,b)=>{
    let va,vb;
    if(key==="priority"){va=PRIOR_ORDER[a.priority]??9;vb=PRIOR_ORDER[b.priority]??9;}
    else if(key==="deadline"){va=a.deadline||"9999";vb=b.deadline||"9999";}
    else if(key==="progress"){va=a.progress??0;vb=b.progress??0;}
    else if(key==="status"){va=STATUS_ORDER[a.status]??9;vb=STATUS_ORDER[b.status]??9;}
    else return 0;
    if(va<vb)return dir==="asc"?-1:1;
    if(va>vb)return dir==="asc"?1:-1;
    return 0;
  });
}

export default function App(){
  const [projects,setProjects]=useState([]);
  const [tasks,setTasks]=useState([]);
  const [pilots,setPilots]=useState([]);
  const [todos,setTodos]=useState([]);
  const [sites,setSites]=useState(SITES);
  const [loading,setLoading]=useState(true);
  const [view,setView]=useState("projects");
  const [fSt,setFSt]=useState(""); const [fPil,setFPil]=useState(""); const [fSite,setFSite]=useState("");
  const [fTPrj,setFTPrj]=useState(""); const [fTSt,setFTSt]=useState(""); const [fTSite,setFTSite]=useState("");
  const [sortKey,setSortKey]=useState(""); const [sortDir,setSortDir]=useState("asc");
  const [pModal,setPModal]=useState(null); const [tModal,setTModal]=useState(null);
  const [gantt,setGantt]=useState(false); const [pilotsModal,setPilotsModal]=useState(false); const [reportModal,setReportModal]=useState(false); const [reunionModal,setReunionModal]=useState(false);
  const [reportDateFrom,setReportDateFrom]=useState(()=>{const d=new Date(TODAY);d.setMonth(d.getMonth()-3);return d.toISOString().split("T")[0];});
  const [reportDateTo,setReportDateTo]=useState(()=>{const d=new Date(TODAY);d.setMonth(d.getMonth()+3);return d.toISOString().split("T")[0];});

  const fetchAll=useCallback(async()=>{
    setLoading(true);
    const [p,t,pl,td,si]=await Promise.all([sbGet("projects"),sbGet("tasks"),sbGet("pilots","*&order=position"),sbGet("todos"),sbGet("sites","*&order=position")]);
    setProjects(Array.isArray(p)?p:[]); setTasks(Array.isArray(t)?t:[]); setPilots(Array.isArray(pl)?pl:[]); setTodos(Array.isArray(td)?td:[]); setSites(Array.isArray(si)&&si.length?si.map(s=>s.name):SITES);
    setLoading(false);
  },[]);
  useEffect(()=>{fetchAll();},[fetchAll]);

  const EP={name:"",status:"En cours",priority:"Moyenne",deadline:"",progress:0,pilot:pilots[0]?.name||"",pilot2:"",site:sites[0]||SITES[0],description:"",notes:"",weight:0,created_at:TODAY};
  const ET={project_id:null,name:"",status:"En attente",priority:"Moyenne",pilot:pilots[0]?.name||"",pilot2:"",site:sites[0]||SITES[0],deadline:"",notes:"",weight:0,created_at:TODAY,completion_date:""};

  async function saveP(f){
    const{id,...d}=f;
    d.progress=calcProgress(f.id,tasks);
    if(pModal.mode==="edit")await sbUpd("projects",id,d);else await sbIns("projects",d);
    setPModal(null);fetchAll();
  }
  async function saveT(f){
    const{id,...d}=f;
    d.project_id=d.project_id?Number(d.project_id):null;
    if(!d.completion_date)d.completion_date=null;
    if(!d.deadline)d.deadline=null;
    if(!d.created_at)d.created_at=TODAY;
    let res;
    if(tModal.mode==="edit")res=await sbUpd("tasks",id,d);else res=await sbIns("tasks",d);
    if(res&&res.error){
      alert("Erreur Supabase ("+res.status+") : "+JSON.stringify(res.detail));
      console.error("Supabase error:",res);
      return;
    }
    if(!res||(Array.isArray(res)&&res.length===0)){
      alert("L'enregistrement n'a renvoyé aucune donnée. Vérifie les policies RLS sur la table tasks.");
      return;
    }
    const pid=d.project_id;
    setTModal(null);
    await fetchAll();
    if(pid){
      const updTasks=await sbGet("tasks");
      const prog=calcProgress(pid,Array.isArray(updTasks)?updTasks:[]);
      await sbUpd("projects",pid,{progress:prog});
      fetchAll();
    }
  }
  async function delP(id){if(!window.confirm("Supprimer ce projet et ses tâches ?"))return;await sbDel("projects",id);fetchAll();}
  async function delT(id){
    const t=tasks.find(x=>x.id===id);
    await sbDel("tasks",id);
    if(t&&t.project_id){const updTasks=tasks.filter(x=>x.id!==id);const prog=calcProgress(t.project_id,updTasks);await sbUpd("projects",t.project_id,{progress:prog});}
    fetchAll();
  }

  function toggleSort(k){if(sortKey===k)setSortDir(d=>d==="asc"?"desc":"asc");else{setSortKey(k);setSortDir("asc");}}
  function sortIcon(k){return sortKey!==k?"↕":sortDir==="asc"?"↑":"↓";}

  const fp=applySort(projects.filter(p=>(!fSt||p.status===fSt)&&(!fPil||p.pilot===fPil)&&(!fSite||p.site===fSite)),sortKey,sortDir);
  const ft=applySort(tasks.filter(t=>(!fTPrj||t.project_id===Number(fTPrj))&&(!fTSt||t.status===fTSt)&&(!fPil||t.pilot===fPil)&&(!fTSite||t.site===fTSite)),sortKey,sortDir);
  const activeN=projects.filter(p=>p.status!=="Terminé").length;
  const odN=tasks.filter(t=>isOD(t.deadline,t.status)).length;
  const doneN=tasks.filter(t=>t.status==="Terminé").length;
  const avgN=projects.length?Math.round(projects.reduce((s,p)=>s+calcProgress(p.id,tasks),0)/projects.length):0;

  // ─── buildReport ────────────────────────────────────────────
  function buildReport(){
    const now=new Date();
    const dl=now.toLocaleDateString("fr-FR",{weekday:"long",year:"numeric",month:"long",day:"numeric"});
    const periodLabel=fd(reportDateFrom)+" → "+fd(reportDateTo);

    // Helpers HTML
    const badge=(label,bg,tx)=>`<span style="background:${bg};color:${tx};font-size:9px;font-weight:700;padding:2px 8px;border-radius:4px;display:inline-block">${label}</span>`;
    const sBadge=s=>{const c=SC[s]||{bg:"#eee",tx:"#333"};return badge(s,c.bg,c.tx);};
    const pBadge=s=>{const c=PC[s]||{bg:"#eee",tx:"#333"};return badge(s,c.bg,c.tx);};
    const siteBadge=s=>{const c=SIC[s]||{bg:"#eee",tx:"#555"};return badge(s,c.bg,c.tx);};
    const bar=(v)=>`<div style="background:#e0e0e0;border-radius:4px;height:8px;width:100%;overflow:hidden"><div style="width:${Math.min(v,100)}%;height:100%;background:${pgCol(v)};border-radius:4px"></div></div>`;

    // ── KPIs ──
    const kpiBlock=`
    <div class="kpi-grid">
      <div class="kpi-card" style="border-top:3px solid #1a6bbf">
        <div class="kpi-label">Projets actifs</div>
        <div class="kpi-value" style="color:#1a6bbf">${activeN}</div>
      </div>
      <div class="kpi-card" style="border-top:3px solid ${odN>0?"#d9534f":"#27500A"}">
        <div class="kpi-label">Tâches en retard</div>
        <div class="kpi-value" style="color:${odN>0?"#d9534f":"#27500A"}">${odN}</div>
      </div>
      <div class="kpi-card" style="border-top:3px solid #639922">
        <div class="kpi-label">Tâches terminées</div>
        <div class="kpi-value" style="color:#639922">${doneN}</div>
      </div>
      <div class="kpi-card" style="border-top:3px solid #BA7517">
        <div class="kpi-label">Avancement moyen</div>
        <div class="kpi-value" style="color:#BA7517">${avgN}%</div>
      </div>
      <div class="kpi-card" style="border-top:3px solid #7F77DD">
        <div class="kpi-label">Total tâches</div>
        <div class="kpi-value" style="color:#7F77DD">${tasks.length}</div>
      </div>
      <div class="kpi-card" style="border-top:3px solid #D85A30">
        <div class="kpi-label">Projets terminés</div>
        <div class="kpi-value" style="color:#D85A30">${projects.filter(p=>p.status==="Terminé").length}</div>
      </div>
    </div>`;

    // ── Tâches en retard ──
    const odT=tasks.filter(t=>isOD(t.deadline,t.status));
    const odBlock=odT.length?`
    <div class="section-block no-break" style="border-left:4px solid #d9534f">
      <div class="section-title" style="color:#d9534f">⚠ Tâches en retard (${odT.length})</div>
      <table>
        <thead><tr><th>Tâche</th><th>Projet</th><th>Pilote</th><th>Site</th><th>Échéance</th></tr></thead>
        <tbody>${odT.map(t=>{
          const prj=projects.find(p=>p.id===t.project_id);
          return`<tr><td style="font-weight:600">${t.name}</td><td>${prj?prj.name:"—"}</td><td>${t.pilot}</td><td>${t.site||"—"}</td><td style="color:#d9534f;font-weight:700">${fd(t.deadline)}</td></tr>`;
        }).join("")}</tbody>
      </table>
    </div>`:"";

    // ── Gantt SVG ──
    const {svg:ganttSvg}=buildGanttSVG(projects,tasks,980);
    const ganttBlock=`
    <div class="section-block">
      <div class="section-title">📅 Diagramme de Gantt</div>
      <div style="overflow:hidden">${ganttSvg}</div>
    </div>`;

    // ── Camembert pilote (SVG inline) ──
    function pilotPieSVG(pilotName,size=100){
      const myT=tasks.filter(t=>t.pilot===pilotName||t.pilot2===pilotName);
      const inProg=myT.filter(t=>t.status!=="Terminé").reduce((s,t)=>s+taskLoadInPeriod(t,reportDateFrom,reportDateTo),0);
      const done=myT.filter(t=>t.status==="Terminé").reduce((s,t)=>s+taskLoadInPeriod(t,reportDateFrom,reportDateTo),0);
      const free=Math.max(0,100-inProg-done);
      const segs=[{v:inProg,c:"#378ADD"},{v:done,c:"#639922"},{v:free,c:"#e0e0e0"}];
      const r=size/2-6,cx=size/2,cy=size/2;
      let acc=0,paths="";
      segs.forEach(s=>{
        if(s.v<=0)return;
        const a1=(acc/100)*2*Math.PI-Math.PI/2; acc+=s.v;
        const a2=(acc/100)*2*Math.PI-Math.PI/2;
        const x1=cx+r*Math.cos(a1),y1=cy+r*Math.sin(a1);
        const x2=cx+r*Math.cos(a2),y2=cy+r*Math.sin(a2);
        const lg=(s.v/100)>0.5?1:0;
        if(s.v>=99.99){paths+=`<circle cx="${cx}" cy="${cy}" r="${r}" fill="${s.c}"/>`;return;}
        paths+=`<path d="M${cx},${cy} L${x1},${y1} A${r},${r} 0 ${lg} 1 ${x2},${y2} Z" fill="${s.c}" stroke="#fff" stroke-width="1.5"/>`;
      });
      const total=Math.round(inProg+done);
      return`<svg width="${size}" height="${size}" xmlns="http://www.w3.org/2000/svg">${paths}<circle cx="${cx}" cy="${cy}" r="${r*0.45}" fill="#fff"/><text x="${cx}" y="${cy+5}" font-size="12" font-weight="bold" text-anchor="middle" fill="#333" font-family="Arial">${total}%</text></svg>`;
    }

    // ── Indicateur délais ──
    function delayInfo(pilotName){
      const d=tasks.filter(t=>(t.pilot===pilotName||t.pilot2===pilotName)&&t.status==="Terminé"&&t.completion_date).map(t=>taskDelay(t)).filter(v=>v!==null);
      if(!d.length)return{label:"Pas de donnée",value:"—",color:"#888",count:0};
      const avg=d.reduce((s,v)=>s+v,0)/d.length;
      return{
        label:avg<=0?"En avance / à l'heure":avg<0.2?"Léger retard":"En retard",
        value:(avg>0?"+":"")+(avg*100).toFixed(0)+"%",
        color:avg<=0?"#27500A":avg<0.2?"#BA7517":"#d9534f",
        count:d.length
      };
    }

    // ── Cards pilotes — chaque card a page-break-inside:avoid ──
    const pilotsBlock=`
    <div class="section-block" style="page-break-inside:avoid">
      <div class="section-title">👥 Statistiques pilotes</div>
      <div class="pilots-grid">
      ${pilots.map((p,pi)=>{
        const col=GCOLS[pi%GCOLS.length];
        const myProj=projects.filter(pr=>pr.pilot===p.name||pr.pilot2===p.name);
        const myT=tasks.filter(t=>t.pilot===p.name||t.pilot2===p.name);
        const active=myProj.filter(pr=>pr.status!=="Terminé").length;
        const tActive=myT.filter(t=>t.status!=="Terminé").length;
        const tDone=myT.filter(t=>t.status==="Terminé").length;
        const delay=delayInfo(p.name);
        const pie=pilotPieSVG(p.name,96);
        const load=myT.filter(t=>t.status!=="Terminé").reduce((s,t)=>s+(t.weight||0),0);
        const loadCol=load>100?"#d9534f":load>80?"#BA7517":"#27500A";
        // Todos filtrés sur la période
        const myTd=(todos||[]).filter(td=>{
          if(td.assigned_to!==p.name)return false;
          if(!reportDateFrom&&!reportDateTo)return true;
          if(!td.due_date)return true;
          if(reportDateFrom&&td.due_date<reportDateFrom)return false;
          if(reportDateTo&&td.due_date>reportDateTo)return false;
          return true;
        }).sort((a,b)=>(a.due_date||"9999")>(b.due_date||"9999")?1:-1);
        const tdPending=myTd.filter(td=>!td.done);
        const tdDone=myTd.filter(td=>td.done);
        const todoSection=myTd.length?`
          <div style="margin-top:8px;border-top:1px solid #eee;padding-top:6px">
            <div style="font-size:8px;color:#BA7517;font-weight:700;margin-bottom:4px;text-transform:uppercase;letter-spacing:0.4px">To-do list (${tdPending.length} en attente · ${tdDone.length} fait${tdDone.length>1?"s":""})</div>
            ${myTd.map(td=>{
              const od=!td.done&&td.due_date&&td.due_date<TODAY;
              return`<div style="display:flex;justify-content:space-between;align-items:center;padding:2px 4px;background:${td.done?"#f3fbee":"#fffbee"};border-radius:3px;margin-bottom:2px;font-size:8px;opacity:${td.done?0.7:1}">
                <span style="font-weight:500;text-decoration:${td.done?"line-through":"none"};flex:1">${td.title}</span>
                <span style="flex-shrink:0;margin-left:6px;background:${td.done?"#EAF3DE":od?"#FCEBEB":"#FAEEDA"};color:${td.done?"#27500A":od?"#791F1F":"#633806"};font-size:7px;font-weight:700;padding:1px 4px;border-radius:2px">${td.done?"✓ Fait":od?"⚠ Retard":"En attente"}</span>
                ${td.due_date?`<span style="font-size:7px;color:${od?"#a32d2d":"#888"};margin-left:4px;flex-shrink:0">${fd(td.due_date)}</span>`:""}
              </div>`;
            }).join("")}
          </div>`:"";
        return`
        <div class="pilot-card" style="border-top:3px solid ${col}">
          <div style="font-weight:700;font-size:11px;color:${col};margin-bottom:8px;display:flex;align-items:center;gap:6px">
            <span style="background:${col};color:#fff;border-radius:50%;width:22px;height:22px;display:inline-flex;align-items:center;justify-content:center;font-size:10px;flex-shrink:0">${p.name[0]}</span>
            ${p.name}
          </div>
          <div style="display:flex;align-items:center;gap:8px;margin-bottom:8px">
            ${pie}
            <div style="font-size:9px;color:#555;line-height:1.8">
              <div>📁 Projets actifs : <b>${active}</b></div>
              <div>✅ Tâches terminées : <b>${tDone}</b></div>
              <div>🔄 En cours : <b>${tActive}</b></div>
            </div>
          </div>
          <div style="background:#f8f8f8;border-radius:5px;padding:6px 8px">
            <div style="font-size:8px;color:#888;margin-bottom:2px;text-transform:uppercase;letter-spacing:0.4px">Respect des délais</div>
            <div style="font-weight:700;font-size:15px;color:${delay.color}">${delay.value}</div>
            <div style="color:${delay.color};font-size:9px">${delay.label}${delay.count?` · ${delay.count} tâche${delay.count>1?"s":""} clôturée${delay.count>1?"s":""}`:""}</div>
          </div>
          ${todoSection}
        </div>`;
      }).join("")}
      </div>
    </div>`;

    // ── Courbe de charge ──
    const chargeSvg=buildChargeSVG(projects,tasks,pilots,970);
    const chargeBlock=`
    <div class="section-block">
      <div class="section-title">📈 Évolution de la charge — 12 mois</div>
      ${chargeSvg}
      <div style="display:flex;flex-wrap:wrap;gap:12px;margin-top:8px">
        ${pilots.map((p,i)=>`<span style="display:flex;align-items:center;gap:5px;font-size:9px"><span style="width:10px;height:10px;border-radius:50%;background:${GCOLS[i%GCOLS.length]};display:inline-block"></span>${p.name}</span>`).join("")}
      </div>
    </div>`;

    // ── Détail projets ──
    const projRows=projects.map((p,pi)=>{
      const pt=tasks.filter(t=>t.project_id===p.id).sort((a,b)=>(a.deadline||"9999")>(b.deadline||"9999")?1:-1);
      const prog=calcProgress(p.id,tasks);
      const od=isOD(p.deadline,p.status);
      const col=GCOLS[pi%GCOLS.length];
      const done=pt.filter(t=>t.status==="Terminé").length;
      return`
      <div class="section-block no-break" style="border-left:4px solid ${col}">
        <div style="display:flex;align-items:flex-start;justify-content:space-between;gap:8px;flex-wrap:wrap;margin-bottom:6px">
          <div>
            <div style="font-weight:700;font-size:12px;color:#111;margin-bottom:4px">${p.name}</div>
            <div style="display:flex;gap:5px;flex-wrap:wrap">${sBadge(p.status)} ${pBadge(p.priority||"Moyenne")} ${p.site?siteBadge(p.site):""}</div>
          </div>
          <div style="text-align:right;font-size:9px;color:#666;line-height:1.8">
            <div>Pilote : <b>${p.pilot}</b>${p.pilot2?` <span style="color:#888;font-size:8px">+ ${p.pilot2}</span>`:""}</div>
            <div style="${od?"color:#d9534f;font-weight:700":""}">Échéance : ${fd(p.deadline)}${od?" ⚠":""}</div>
            <div>${done}/${pt.length} tâche${pt.length>1?"s":""} terminée${pt.length>1?"s":""}</div>
          </div>
        </div>
        <div style="display:flex;align-items:center;gap:8px;margin-bottom:6px">
          <div style="flex:1">${bar(prog)}</div>
          <span style="font-size:11px;font-weight:700;color:${pgCol(prog)};white-space:nowrap;min-width:36px;text-align:right">${prog}%</span>
        </div>
        ${p.notes?`<div style="font-size:9px;color:#555;background:#fffbee;border:1px solid #f0e68c;border-radius:4px;padding:4px 8px;margin-bottom:6px">📝 ${p.notes}</div>`:""}
        ${pt.length?`
        <table>
          <thead><tr><th>Tâche</th><th>Statut</th><th>Pilote</th><th>Pondération</th><th>Échéance</th><th>Fin réelle</th></tr></thead>
          <tbody>${pt.map(t=>{
            const tod=isOD(t.deadline,t.status);
            const sc2=SC[t.status]||{bg:"#eee",tx:"#333"};
            return`<tr>
              <td style="font-weight:500">${t.name}${t.notes?` <span style="color:#BA7517">📝</span>`:""}</td>
              <td>${badge(t.status,sc2.bg,sc2.tx)}</td>
              <td>${t.pilot}${t.pilot2?` <span style="color:#888;font-size:8px">+${t.pilot2}</span>`:""}</td>
              <td style="text-align:center">${(t.weight||0)>0?`<span style="background:#f0f0f0;font-size:8px;padding:1px 5px;border-radius:3px">${t.weight}%</span>`:"—"}</td>
              <td style="${tod?"color:#d9534f;font-weight:700":""}">${fd(t.deadline)}${tod?" ⚠":""}</td>
              <td>${t.completion_date?fd(t.completion_date):"—"}</td>
            </tr>`;
          }).join("")}</tbody>
        </table>`:`<p style="font-size:10px;color:#aaa;margin:0;padding:4px 0">Aucune tâche associée.</p>`}
      </div>`;
    }).join("");

    // ── Tâches indépendantes ──
    const indepTasks=tasks.filter(t=>!t.project_id);
    const indepBlock=indepTasks.length?`
    <div class="section-block">
      <div class="section-title">📌 Tâches indépendantes (${indepTasks.length})</div>
      <table>
        <thead><tr><th>Tâche</th><th>Statut</th><th>Pilote</th><th>Site</th><th>Échéance</th><th>Fin réelle</th></tr></thead>
        <tbody>${indepTasks.map(t=>{
          const tod=isOD(t.deadline,t.status);
          const sc2=SC[t.status]||{bg:"#eee",tx:"#333"};
          return`<tr>
            <td>${t.name}</td>
            <td>${badge(t.status,sc2.bg,sc2.tx)}</td>
            <td>${t.pilot}</td>
            <td>${t.site||"—"}</td>
            <td style="${tod?"color:#d9534f;font-weight:700":""}">${fd(t.deadline)}${tod?" ⚠":""}</td>
            <td>${t.completion_date?fd(t.completion_date):"—"}</td>
          </tr>`;
        }).join("")}</tbody>
      </table>
    </div>`:"";


    // ── To-do list filtrée sur la période ──
    function todoInPeriod(t){
      if(!t.due_date)return true;
      if(reportDateFrom&&t.due_date<reportDateFrom)return false;
      if(reportDateTo&&t.due_date>reportDateTo)return false;
      return true;
    }
    const todosInPeriod=[...todos].filter(todoInPeriod);
    const pendingTodos=todosInPeriod.filter(t=>!t.done);
    const doneTodos=todosInPeriod.filter(t=>t.done);

    function buildTodoRow(t){
      const od=!t.done&&t.due_date&&t.due_date<TODAY;
      const badgeDone='<span style="background:#EAF3DE;color:#27500A;font-size:9px;font-weight:700;padding:2px 7px;border-radius:4px">&#10003; Fait</span>';
      const badgePending='<span style="background:#FAEEDA;color:#633806;font-size:9px;font-weight:700;padding:2px 7px;border-radius:4px">En attente</span>';
      const badgeOverdue='<span style="background:#FCEBEB;color:#791F1F;font-size:9px;font-weight:700;padding:2px 7px;border-radius:4px">&#9888; En retard</span>';
      return '<tr style="opacity:'+(t.done?0.6:1)+'">'
        +'<td style="text-align:center;font-size:14px">'+(t.done?"&#9745;":"&#9744;")+'</td>'
        +'<td style="font-weight:'+(t.done?"400":"600")+';text-decoration:'+(t.done?"line-through":"none")+';color:'+(t.done?"#aaa":"#111")+'">'+t.title+'</td>'
        +'<td>'+(t.assigned_to||"—")+'</td>'
        +'<td style="'+(od?"color:#d9534f;font-weight:700":"")+'">'+(t.due_date?fd(t.due_date):"—")+'</td>'
        +'<td>'+(t.done?badgeDone:od?badgeOverdue:badgePending)+'</td>'
        +'</tr>';
    }

    const todoRows=[...todosInPeriod].sort((a,b)=>{
      if(a.done!==b.done)return a.done?1:-1;
      const aOD=!a.done&&a.due_date&&a.due_date<TODAY;
      const bOD=!b.done&&b.due_date&&b.due_date<TODAY;
      if(aOD!==bOD)return aOD?-1:1;
      return (a.due_date||"9999")<(b.due_date||"9999")?-1:1;
    }).map(t=>buildTodoRow(t)).join("");

    const todoBlock=todosInPeriod.length
      ?'<div class="section-block no-break">'
        +'<div class="section-title">&#10003; To-do list &mdash; p&eacute;riode '+fd(reportDateFrom)+' &rarr; '+fd(reportDateTo)+' ('+pendingTodos.length+' en attente &middot; '+doneTodos.length+' fait'+(doneTodos.length>1?"s":"")+')</div>'
        +'<table>'
        +'<thead><tr><th style="width:30px"></th><th>Intitul&eacute;</th><th>Assign&eacute; &agrave;</th><th>Date limite</th><th>Statut</th></tr></thead>'
        +'<tbody>'+todoRows+'</tbody>'
        +'</table>'
        +'</div>'
      :"";

    // ── CSS ──
    const css=`
      *{box-sizing:border-box;margin:0;padding:0}
      body{font-family:Arial,sans-serif;font-size:10px;color:#222;background:#eef0f4}
      @page{size:A4 landscape;margin:8mm 10mm}
      @media print{
        body{background:#fff}
        .no-break{page-break-inside:avoid;break-inside:avoid}
        .page-break{page-break-before:always;break-before:always}
        .section-block{page-break-inside:avoid;break-inside:avoid}
        .pilot-card{page-break-inside:avoid;break-inside:avoid}
        .pilots-grid{break-inside:avoid}
      }
      .page{background:#fff;max-width:1020px;margin:0 auto;padding:16px 20px}
      .report-header{background:linear-gradient(135deg,#1a6bbf 0%,#0d3f7a 100%);color:#fff;border-radius:10px;padding:14px 22px;margin-bottom:14px;display:flex;justify-content:space-between;align-items:center}
      .report-logo{width:60px;height:60px;object-fit:contain;background:#fff;border-radius:8px;padding:4px;flex-shrink:0;margin-right:16px}
      .report-title{font-size:17px;font-weight:700;margin-bottom:4px;letter-spacing:0.3px}
      .report-sub{font-size:9.5px;opacity:0.82;line-height:1.6}
      .report-month{background:rgba(255,255,255,0.18);border-radius:8px;padding:8px 16px;text-align:center;font-size:10px;font-weight:600;border:1px solid rgba(255,255,255,0.25)}
      .report-month span{font-size:15px;font-weight:700;display:block;line-height:1.5;white-space:nowrap}
      .kpi-grid{display:grid;grid-template-columns:repeat(6,1fr);gap:8px;margin-bottom:14px}
      .kpi-card{background:#fff;border:1px solid #dde3f0;border-radius:8px;padding:10px 10px 8px;text-align:center;box-shadow:0 1px 4px rgba(0,0,0,0.06)}
      .kpi-label{font-size:8px;color:#777;margin-bottom:5px;font-weight:600;text-transform:uppercase;letter-spacing:0.5px}
      .kpi-value{font-size:24px;font-weight:700;line-height:1}
      .section-block{background:#fff;border:1px solid #dde3f0;border-radius:8px;padding:12px 14px;margin-bottom:12px;box-shadow:0 1px 4px rgba(0,0,0,0.04)}
      .section-title{font-size:11px;font-weight:700;color:#1a6bbf;margin-bottom:10px;padding-bottom:5px;border-bottom:2px solid #e8edf5;letter-spacing:0.3px}
      .pilots-grid{display:grid;grid-template-columns:repeat(3,1fr);gap:10px}
      .pilot-card{background:#fff;border:1px solid #dde3f0;border-radius:8px;padding:12px;page-break-inside:avoid;break-inside:avoid}
      table{width:100%;border-collapse:collapse;font-size:9.5px}
      th{padding:4px 8px;text-align:left;background:#f0f4fa;color:#444;font-weight:700;border-bottom:2px solid #dde3f0}
      td{padding:4px 8px;border-bottom:1px solid #f2f2f2;vertical-align:middle}
      tr:last-child td{border-bottom:none}
      tr:nth-child(even) td{background:#fafbfd}
      .footer{text-align:center;font-size:8px;color:#aaa;margin-top:14px;padding-top:8px;border-top:1px solid #eee;line-height:1.6}
    `;

    // ── Assemblage final ──
    return`<!DOCTYPE html><html lang="fr"><head><meta charset="UTF-8"><title>Bilan mensuel — Physique Médicale</title><style>${css}</style></head>
    <body><div class="page">

      <div class="report-header">
        <img class="report-logo" src="${LOGO_URI}" alt="Logo"/>
        <div style="flex:1">
          <div class="report-title">Bilan mensuel — Physique Médicale</div>
          <div class="report-sub">Sites Galilée &amp; Bourgogne &nbsp;·&nbsp; ${dl}</div>
          <div class="report-sub" style="margin-top:3px;opacity:0.55">Document confidentiel — usage interne uniquement</div>
        </div>
        <div class="report-month">Période<span>${periodLabel}</span></div>
        </div>
      </div>

      ${kpiBlock}
      ${odBlock}
      ${ganttBlock}

      <div class="page-break"></div>

      ${chargeBlock}
      ${pilotsBlock}

      <div class="page-break"></div>

      <div style="font-size:13px;font-weight:700;color:#1a6bbf;padding-bottom:6px;border-bottom:2px solid #1a6bbf;margin-bottom:12px">
        📁 Détail des projets (${projects.length})
      </div>
      ${projRows}
      ${indepBlock}
      ${todoBlock}

      <div class="footer">
        Rapport généré le ${now.toLocaleDateString("fr-FR",{day:"numeric",month:"long",year:"numeric"})} à ${now.toLocaleTimeString("fr-FR",{hour:"2-digit",minute:"2-digit"})}
        &nbsp;·&nbsp; Physique Médicale — Sites Galilée &amp; Bourgogne &nbsp;·&nbsp; Document confidentiel
      </div>

    </div></body></html>`;
  }

  if(loading)return <Spinner/>;

  return(
    <div style={{padding:"1rem 0",fontFamily:"Arial,sans-serif",color:"#111"}}>
      {pModal&&<Modal title={pModal.mode==="edit"?"Modifier le projet":"Nouveau projet"} onClose={()=>setPModal(null)}><ProjForm data={pModal.data} pilots={pilots} tasks={tasks} onSave={saveP} onClose={()=>setPModal(null)}/></Modal>}
      {tModal&&<Modal title={tModal.mode==="edit"?"Modifier la tâche":"Nouvelle tâche"} onClose={()=>setTModal(null)}><TaskForm data={tModal.data} projects={projects} pilots={pilots} onSave={saveT} onClose={()=>setTModal(null)}/></Modal>}
      {gantt&&<Modal title="Gantt — cliquer ▶ pour voir les tâches" onClose={()=>setGantt(false)} wide><GanttView projects={projects} tasks={tasks}/><div style={{textAlign:"right",marginTop:12}}><button style={ss.btnS} onClick={()=>setGantt(false)}>Fermer</button></div></Modal>}
      {pilotsModal&&<Modal title="Gérer les pilotes & centres" onClose={()=>setPilotsModal(false)} wide={false}><PilotsForm pilots={pilots} sites={sites} onClose={()=>setPilotsModal(false)} onRefresh={fetchAll}/></Modal>}
      {reportModal&&<ReportModal html={buildReport()} onClose={()=>setReportModal(false)}/> }
      {reunionModal&&<ReunionModal onClose={()=>{ setReunionModal(false); fetchAll(); }}/>}

      <div style={{display:"flex",justifyContent:"space-between",alignItems:"center",marginBottom:12}}>
        <div style={{display:"flex",alignItems:"center",gap:12}}>
          <img src={LOGO_URI} alt="Logo" style={{width:52,height:52,objectFit:"contain",background:"linear-gradient(135deg,#1a6bbf,#0d3f7a)",borderRadius:10,padding:6,flexShrink:0}}/>
          <div>
            <div style={{fontSize:17,fontWeight:700}}>Suivi des projets — Physique Médicale</div>
            <div style={{fontSize:11,color:"#666",marginTop:2}}>Sites Galilée &amp; Bourgogne</div>
          </div>
        </div>
        <div style={{display:"flex",gap:8,flexWrap:"wrap",justifyContent:"flex-end"}}>
          <button style={ss.btnS} onClick={fetchAll}>↻</button>
          <button style={ss.btnS} onClick={()=>setPilotsModal(true)}>👥 Pilotes</button>
          <button style={ss.btnS} onClick={()=>setGantt(true)}>Gantt</button>
          <button style={{...ss.btnS,background:"#1D9E75",color:"#fff",border:"none"}} onClick={()=>setReunionModal(true)}>🗓 Réunion de service</button>
          <button style={ss.btnP} onClick={()=>setReportModal(true)}>Bilan PDF</button>
        </div>
      </div>

      <div style={{display:"grid",gridTemplateColumns:"repeat(4,1fr)",gap:10,marginBottom:16}}>
        {[{l:"Projets actifs",v:activeN},{l:"Tâches en retard",v:odN,d:odN>0},{l:"Tâches terminées",v:doneN},{l:"Avancement moyen",v:avgN+"%"}].map(k=>(
          <div key={k.l} style={{background:"#f4f4f4",borderRadius:8,padding:"9px 11px"}}>
            <div style={{fontSize:10,color:k.d?"#a32d2d":"#666",marginBottom:3}}>{k.l}</div>
            <div style={{fontSize:22,fontWeight:700,color:k.d?"#a32d2d":"#111"}}>{k.v}</div>
          </div>
        ))}
      </div>

      <div style={{display:"flex",borderBottom:"1px solid #ddd",marginBottom:12}}>
        {[["projects","Projets ("+projects.length+")"],["tasks","Tâches ("+tasks.length+")"],["stats","Statistiques pilotes"],["todo","To-do list ✓ ("+todos.filter(t=>!t.done).length+"/"+todos.length+")"]].map(([v,l])=>(
          <button key={v} onClick={()=>setView(v)} style={{padding:"6px 15px",fontSize:12,background:"none",border:"none",borderBottom:view===v?"2px solid #111":"2px solid transparent",color:view===v?"#111":"#666",cursor:"pointer",fontWeight:view===v?700:400}}>{l}</button>
        ))}
      </div>

      {view==="todo"&&<TodoView pilots={pilots} todos={todos} onRefresh={fetchAll}/> }
      {view==="stats"&&<StatsView projects={projects} tasks={tasks} pilots={pilots} todos={todos} dateFrom={reportDateFrom} setDateFrom={setReportDateFrom} dateTo={reportDateTo} setDateTo={setReportDateTo}/>}

      {view!=="stats"&&view!=="todo"&&<>
        <div style={{display:"flex",gap:8,marginBottom:8,flexWrap:"wrap",alignItems:"center"}}>
          <select style={ss.sel} value={fSt} onChange={e=>setFSt(e.target.value)}><option value="">Tous les statuts</option>{STATUSES.map(s=><option key={s}>{s}</option>)}</select>
          <select style={ss.sel} value={fPil} onChange={e=>setFPil(e.target.value)}><option value="">Tous les pilotes</option>{pilots.map(p=><option key={p.id}>{p.name}</option>)}</select>
          {view==="projects"&&<select style={ss.sel} value={fSite} onChange={e=>setFSite(e.target.value)}><option value="">Tous les sites</option>{SITES.map(s=><option key={s}>{s}</option>)}</select>}
          {view==="tasks"&&<><select style={ss.sel} value={fTPrj} onChange={e=>setFTPrj(e.target.value)}><option value="">Tous les projets</option>{projects.map(p=><option key={p.id} value={p.id}>{p.name}</option>)}</select><select style={ss.sel} value={fTSt} onChange={e=>setFTSt(e.target.value)}><option value="">Tous les statuts</option>{STATUSES.map(s=><option key={s}>{s}</option>)}</select><select style={ss.sel} value={fTSite} onChange={e=>setFTSite(e.target.value)}><option value="">Tous les sites</option>{SITES.map(s=><option key={s}>{s}</option>)}</select></>}
          <div style={{marginLeft:"auto"}}>
            {view==="projects"&&<button style={ss.btnP} onClick={()=>setPModal({mode:"add",data:{...EP,pilot:pilots[0]?.name||""}})}>+ Nouveau projet</button>}
            {view==="tasks"&&<button style={ss.btnP} onClick={()=>setTModal({mode:"add",data:{...ET,pilot:pilots[0]?.name||""}})}>+ Nouvelle tâche</button>}
          </div>
        </div>
        <div style={{display:"flex",gap:6,marginBottom:12,flexWrap:"wrap",alignItems:"center"}}>
          <span style={{fontSize:11,color:"#666"}}>Trier :</span>
          {[{k:"priority",l:"Priorité"},{k:"deadline",l:"Échéance"},{k:"progress",l:"Avancement"},{k:"status",l:"Statut"}].map(({k,l})=>(
            <button key={k} onClick={()=>toggleSort(k)} style={{...ss.btnS,fontSize:11,padding:"3px 9px",background:sortKey===k?"#e8f0fb":"#f0f0f0",color:sortKey===k?"#1a6bbf":"#333",fontWeight:sortKey===k?700:400}}>{l} {sortIcon(k)}</button>
          ))}
          {view==="projects"&&<button onClick={()=>toggleSort("site")} style={{...ss.btnS,fontSize:11,padding:"3px 9px",background:sortKey==="site"?"#e8f0fb":"#f0f0f0",color:sortKey==="site"?"#1a6bbf":"#333",fontWeight:sortKey==="site"?700:400}}>Site {sortIcon("site")}</button>}
          {sortKey&&<button onClick={()=>setSortKey("")} style={{...ss.btnD,fontSize:11,padding:"3px 9px"}}>✕</button>}
        </div>
      </>}

      {view==="projects"&&<div>
        {fp.length===0&&<p style={{color:"#888",fontSize:13}}>Aucun projet.</p>}
        {fp.map(p=>{
          const tc=tasks.filter(t=>t.project_id===p.id).length;
          const prog=calcProgress(p.id,tasks);
          const od=isOD(p.deadline,p.status);
          const done=tasks.filter(t=>t.project_id===p.id&&t.status==="Terminé").length;
          return(
            <div key={p.id} style={{background:"#fff",border:"1px solid #e0e0e0",borderRadius:10,padding:"11px 13px",marginBottom:9}}>
              <div style={{display:"flex",alignItems:"flex-start",gap:8,flexWrap:"wrap",marginBottom:5}}>
                <span style={{fontWeight:700,fontSize:13,flex:1}}>{p.name}</span>
                <Badge label={p.status} c={SC[p.status]||{bg:"#eee",tx:"#333"}}/>
                <Badge label={p.priority||"Moyenne"} c={PC[p.priority||"Moyenne"]}/>
                {p.site&&<Badge label={p.site} c={SIC[p.site]||{bg:"#eee",tx:"#555"}}/>}
              </div>
              {p.description&&<div style={{fontSize:11,color:"#666",marginBottom:5}}>{p.description}</div>}
              {p.notes&&<div style={{fontSize:11,color:"#555",background:"#fffbee",border:"1px solid #f0e68c",borderRadius:6,padding:"5px 9px",marginBottom:6,whiteSpace:"pre-wrap"}}>📝 {p.notes}</div>}
              <div style={{display:"flex",gap:12,fontSize:11,color:"#666",marginBottom:7,flexWrap:"wrap"}}>
                <span>Pilote : {p.pilot}{p.pilot2&&<span style={{color:"#888"}}> + {p.pilot2}</span>}</span>
                {p.deadline&&<span style={{color:od?"#a32d2d":"#666"}}>Échéance : {fd(p.deadline)}{od?" (!!)":""}</span>}
                <span style={{color:"#bbb"}}>Ajouté : {fd(p.created_at)}</span>
                <span>{done}/{tc} tâche{tc>1?"s":""} terminée{done>1?"s":""}</span>
              </div>
              <div style={{display:"flex",alignItems:"center",gap:8,marginBottom:9}}>
                <PBar v={prog}/><span style={{fontSize:11,color:"#666",minWidth:32}}>{prog}%</span>
              </div>
              <div style={{display:"flex",gap:6}}>
                <button style={ss.btnS} onClick={()=>setPModal({mode:"edit",data:{...p}})}>Modifier</button>
                <button style={ss.btnS} onClick={()=>{setView("tasks");setFTPrj(String(p.id));}}>Tâches</button>
                <button style={ss.btnD} onClick={()=>delP(p.id)}>Supprimer</button>
              </div>
            </div>
          );
        })}
      </div>}

      {view==="tasks"&&<div>
        {ft.length===0&&<p style={{color:"#888",fontSize:13}}>Aucune tâche.</p>}
        {ft.map(t=>{
          const prj=projects.find(p=>p.id===t.project_id),od=isOD(t.deadline,t.status);
          return(
            <div key={t.id} style={{background:"#fff",border:"1px solid "+(od?"#f09595":"#e0e0e0"),borderRadius:8,padding:"9px 12px",marginBottom:7}}>
              <div style={{display:"flex",alignItems:"center",gap:8,flexWrap:"wrap",marginBottom:t.notes?6:0}}>
                <div style={{flex:1,minWidth:140}}>
                  <div style={{fontWeight:700,fontSize:12}}>{t.name}</div>
                  <div style={{fontSize:10,color:"#888"}}>{prj?prj.name:"— Indépendante —"}</div>
                </div>
                <Badge label={t.status} c={SC[t.status]||{bg:"#eee",tx:"#333"}}/>
                {t.priority&&<Badge label={t.priority} c={PC[t.priority]||{bg:"#eee",tx:"#555"}}/>}
                {t.site&&<Badge label={t.site} c={SIC[t.site]||{bg:"#eee",tx:"#555"}}/>}
                <span style={{fontSize:11,color:"#666"}}>Pilote : {t.pilot}{t.pilot2&&<span style={{color:"#888"}}> + {t.pilot2}</span>}</span>
                {t.deadline&&<span style={{fontSize:11,color:od?"#a32d2d":"#666"}}>Éch. {fd(t.deadline)}{od?" (!!)":""}</span>}
                {t.completion_date&&<span style={{fontSize:11,color:"#27500A"}}>Fin réelle : {fd(t.completion_date)}</span>}
                <span style={{fontSize:10,color:"#bbb"}}>Début : {fd(t.created_at)}</span>
                {(t.weight||0)>0&&<span style={{background:"#f0f0f0",borderRadius:4,padding:"1px 7px",fontSize:10,color:"#555",fontWeight:600}}>⏱ {t.weight}%</span>}
                <div style={{display:"flex",gap:6,marginLeft:"auto"}}>
                  <button style={ss.btnS} onClick={()=>setTModal({mode:"edit",data:{...t}})}>Modifier</button>
                  <button style={ss.btnD} onClick={()=>delT(t.id)}>Suppr.</button>
                </div>
              </div>
              {t.notes&&<div style={{fontSize:11,color:"#555",background:"#fffbee",border:"1px solid #f0e68c",borderRadius:5,padding:"4px 9px",whiteSpace:"pre-wrap"}}>📝 {t.notes}</div>}
            </div>
          );
        })}
      </div>}
    </div>
  );
}
